-- NaCCA curriculum for Basic 8 (part 2 of 2): 64 indicators (Science, Social Studies).
-- Needs 20261029_curriculum_subject_key.sql first. Safe to run again: it replaces these subjects for Basic 8.
delete from public.curriculum_items
 where lower(class_name) = 'basic 8' and subject_key in ('science', 'social studies');

