insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 8', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B8.1.1.1', 'Demonstrate knowledge of types of mixtures, and understanding of the processes of scientific ways of separating the components of mixtures', 'B8.1.1.1.1', 'Identify types of mixtures by name and characteristics', '1. Group materials such as powder, pebbles, bottle tops, salt, sugar, sand, gari, gravel, oil, water and others into two main categories: solids and liquids.; 2. Put any two of the materials (in; 1) together and describe the resultant nature of the product formed.; 3. Draw observable conclusions on homogeneous and heterogeneous characteristics from mixtures of two or more materials such as sand and gravel; sand and water; oil and water.; 4. Compare and contrast solutes and solvents based on their physical characteristics.; 5. Identify and separate mixtures such as sand and sugar mixture, sugar and salt mixture and solutions such as salt solution, sugar solution, fruit juice, vinegar solution based on their physical properties.; 6. Identify a suspension as a type of mixture e.g. mixture of groundnut paste and water in a glass.; 7. Differentiate between a colloid and a suspension and show the colloidal effect.', 10),
('Basic 8', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B8.1.1.1', 'Demonstrate knowledge of types of mixtures, and understanding of the processes of scientific ways of separating the components of mixtures', 'B8.1.1.1.2', 'Design and perform processes for separating kinds of mixtures', '1. Perform activities such as distilling, filtering, sieving and others to separate different kinds of mixtures and present a report on your findings using drawing and written work.', 20),
('Basic 8', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B8.1.1.2', 'Demonstrate understanding of atoms and the atomic structure of elements in the periodic table', 'B8.1.1.2.1', 'Describe atoms as composed of sub-atomic particles', '1. Explain an atom and its structure of an element using/linking it to the periodic table.; 2. List the sub-atomic particles found in the atom and indicate their location in the atom (e.g. proton, electron, neutron).; 3. State the electrical charges on the sub-atomic particles.; 4. Describe the differences between the atomic number and the mass number of elements.; 5. Determine the number of protons, neutrons and electrons in an atom.', 30),
('Basic 8', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B8.1.1.2', 'Demonstrate understanding of atoms and the atomic structure of elements in the periodic table', 'B8.1.1.2.2', 'Explain the arrangement of elements in terms of the number of protons in the nuclei of atoms of each element', '1. Explain how elements are arranged in order of the number of protons using the periodic table.; 2. Draw the distribution of electrons (electron configuration) in the atoms.; 3. Explain the formation of ions.; 4. Describe a molecule as a combination of atoms.', 40),
('Basic 8', 'Science', 'science', 'Diversity of Matter', 'Living Cells', 'B8.1.2.1', 'Demonstrate an understanding of the types of cells and their structure in relation to different organisms', 'B8.1.2.1.1', 'Examine and describe the structure of prokaryotic and eukaryotic cells', '1. Compare and contrast prokaryotic and eukaryotic cells.; 2. Create a table to show a chart or a slideshow depicting images and labels of the types of cells. Identify their differences and similarities after observation.; 3. Draw and label a prokaryotic cell and a eukaryotic cell and make a presentation on what is observed.', 50),
('Basic 8', 'Science', 'science', 'Diversity of Matter', 'Living Cells', 'B8.1.2.1', 'Demonstrate an understanding of the types of cells and their structure in relation to different organisms', 'B8.1.2.1.2', 'Classify organisms (plants or animals) as prokaryotic or eukaryotic based on the type of cells they are made of', '1. Observe and list examples of organisms; plants and animals as prokaryotic or eukaryotic based on each cell type.; 2. Explain the impact of prokaryotes and eukaryotes on humans health and devise safety measures to protect them.', 60),
('Basic 8', 'Science', 'science', 'Cycles', 'Earth Science', 'B8.2.1.1', 'Demonstrate understanding of the process of Carbon cycle as an example of repeated pattern of change in nature and how it relates to the environment', 'B8.2.1.1.1', 'Explain the process of the carbon cycle', '1. Identify the carbon cycle from the internet, charts or pictures and write short notes on what happens at each stage.; 2. Produce a flow chart to trace the process of the carbon cycle in nature.; 3. Explain the process of the carbon cycle depicting processes such as a) Photosynthesis b) Respiration c) Burning d) Decay.; 4. Compile information on the carbon cycle and give reasons why it is a repeated pattern e.g. it is because the carbon is circulated continuously in the environment.', 70),
('Basic 8', 'Science', 'science', 'Cycles', 'Earth Science', 'B8.2.1.1', 'Demonstrate understanding of the process of Carbon cycle as an example of repeated pattern of change in nature and how it relates to the environment', 'B8.2.1.1.2', 'Describe the role of the carbon cycle to the environment', '1. Describe the role of the carbon cycle in maintaining balance in the composition of air in the environment. E.g. plants absorb carbon in the form of Carbon (IV) Oxide from the air for photosynthesis and oxygen is produced for respiration and in return, respiration gives out carbon in the form of Carbon (IV) Oxide. Note: Discuss photosynthesis and respiration in plants as part of the carbon cycle.; 2. Explain the effect of the carbon cycle on food chains, using diagrams.; 3. Describe the relationship between greenhouse gases and the carbon cycle.', 80),
('Basic 8', 'Science', 'science', 'Cycles', 'Life Cycle of Organisms', 'B8.2.2.1', 'Demonstrate an activity to show the life cycle of the Anopheles mosquito and show how the effects of the mosquito on humans can be managed', 'B8.2.2.1.1', 'Describe the life cycle and economic importance of the Anopheles mosquito', '1. Observe and draw the different stages of the life cycle of the Anopheles mosquito e.g. by breeding the mosquito in a glass jar.; 2. Describe the economic importance of the Anopheles mosquito.', 90),
('Basic 8', 'Science', 'science', 'Cycles', 'Life Cycle of Organisms', 'B8.2.2.1', 'Demonstrate an activity to show the life cycle of the Anopheles mosquito and show how the effects of the mosquito on humans can be managed', 'B8.2.2.1.2', 'Discuss the impact of the Anopheles mosquito on humans and how it can be controlled', '1. Discuss the impact of the female Anopheles mosquito as a vector of plasmodium on humans.; 2. Generate solutions to control malaria in Ghana.', 100),
('Basic 8', 'Science', 'science', 'Cycles', 'Crop Production', 'B8.2.3.1', 'Demonstrate knowledge and skills in planting crops on different seed beds', 'B8.2.3.1.1', 'Explore the different seed beds for planting crops in your community', '1. Observe and discuss different seed beds for planting different crops.; 2. List and compare the differences and similarities among seed beds in the community.; 3. Match the types of seed beds with the types and stages of crops planted in your community.', 110),
('Basic 8', 'Science', 'science', 'Cycles', 'Crop Production', 'B8.2.3.1', 'Demonstrate knowledge and skills in planting crops on different seed beds', 'B8.2.3.1.2', 'Plant different types of crops on different seed beds', '1. Observe and discuss the practice of planting different crops in different seed beds.; 2. Select different plant parts, (seeds, seedlings, cuttings, leaves, roots) and plant them in different seed beds.', 120),
('Basic 8', 'Science', 'science', 'Cycles', 'Crop Production', 'B8.2.3.2', 'Demonstrate understanding of the differences in height, size, and flowering of crops grown in different seed beds', 'B8.2.3.2.1', 'Compare and contrast the differences in height, size, and flowering of crops grown in different seed beds', '1. Measure the heights, sizes, number of flowers, and number of fruits of plants grown in different seed beds.; 2. Discuss the differences and similarities in the heights, sizes, number of flowers and fruits of plants grown in different seed beds using tables and graphs.; 3. Write and give presentations on the reasons for differences in the heights, sizes, number of flowers and fruits of plants grown in different seed beds.', 130),
('Basic 8', 'Science', 'science', 'Cycles', 'Animal Production', 'B8.2.4.1', 'Recognise the different types of feed for different types of animals', 'B8.2.4.1.1', 'Compare and contrast the different types of feed for different types of animals', '1. Match the different types of feed with different types of animals.; 2. Discuss the types of nutrients and their sources in the different types of animal feed.; 3. Select and discuss appropriate feed for animal based on the proportions of nutrients indicated on the package or labels.', 140),
('Basic 8', 'Science', 'science', 'Cycles', 'Animal Production', 'B8.2.4.2', 'Demonstrate understanding of the importance of water and animal feed to the growth of animals', 'B8.2.4.2.1', 'Explain the importance of water and animal feed to the growth of animals', '1. List and discuss the usefulness of water and feed for the growth and reproduction of animals.; 2. Predict what will happen to animals who are not provided with adequate water.', 150),
('Basic 8', 'Science', 'science', 'Systems', 'The Human Body System', 'B8.3.1.1', 'Demonstrate knowledge of parts of mammalian tooth and the functions of the different types of teeth in relation to feeding in man', 'B8.3.1.1.1', 'Identify parts of a mammalian tooth', '1. Label parts, such as crown, neck, and root of a mammalian tooth.; 2. Explain the functions of each part of the mammalian tooth of humans.', 160),
('Basic 8', 'Science', 'science', 'Systems', 'The Human Body System', 'B8.3.1.1', 'Demonstrate knowledge of parts of mammalian tooth and the functions of the different types of teeth in relation to feeding in man', 'B8.3.1.1.2', 'Discuss the functions of the different types of teeth such as incisors, canines, premolars, and molars', '1. Discuss the functions of the different types of human teeth.; 2. Draw the different types of teeth.', 170),
('Basic 8', 'Science', 'science', 'Systems', 'The Human Body System', 'B8.3.1.1', 'Demonstrate knowledge of parts of mammalian tooth and the functions of the different types of teeth in relation to feeding in man', 'B8.3.1.1.3', 'Explain the causes and prevention of tooth and gum decay', '1. Describe the causes of tooth decay, gum diseases and formation of plaque and the proper way of preventing tooth decay.; 2. Demonstrate proper ways of cleaning the teeth.', 180),
('Basic 8', 'Science', 'science', 'Systems', 'The Solar System', 'B8.3.2.1', 'Demonstrate knowledge of the outer planets of the solar system', 'B8.3.2.1.1', 'Identify the outer planets of the solar system and describe their properties', '1. Describe the composition of the solar system using charts, pictures and digital content.; 2. Identify and draw the planets that form the outer solar system.; 3. Discuss the properties that are peculiar to each of the planet: Jupiter, Saturn, Uranus, and Neptune.; 4. Search and explain why there is no life on Jupiter, Saturn, Uranus, and Neptune.; 5. Construct a model of the outer solar system (Jupiter, Saturn, Uranus, and Neptune) and display it for discussion.', 190),
('Basic 8', 'Science', 'science', 'Systems', 'Ecosystem', 'B8.3.3.1', 'Demonstrate an understanding of the interdependence of organisms in an ecosystem and their interaction', 'B8.3.3.1.1', 'Explore the feeding relationships within an ecosystem', '1. Discuss how life on earth will be like without the sun.; 2. Explain the terms: producer, primary consumer, secondary consumer, food chain and food web as applied in energy transfer in an ecosystem.; 3. Illustrate with diagrams how energy from the sun flows through a food chain and food web in an ecosystem.', 200),
('Basic 8', 'Science', 'science', 'Systems', 'Farming Systems', 'B8.3.4.1', 'Demonstrate understanding of the different crop, animal and land combinations under various farming systems', 'B8.3.4.1.1', 'Identify and describe the types of crops, animals and land combinations for the different farming systems', '1. Describe the types of crops, animals and land combinations in the different farming systems in your community.; 2. Discuss the advantages and disadvantages of each farming system identified.', 210),
('Basic 8', 'Science', 'science', 'Systems', 'Farming Systems', 'B8.3.4.1', 'Demonstrate understanding of the different crop, animal and land combinations under various farming systems', 'B8.3.4.1.2', 'Discuss the usefulness of the different crops and animals involved in the different farming systems', '1. Explain how the different components of farming systems contribute to each other.; 2. Discuss and write down the contributions of crops and animals towards the sustainability of each farming system.', 220),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Energy', 'B8.4.1.1', 'Demonstrate the skill to evaluate the conversion of energy from one form to another', 'B8.4.1.1.1', 'Describe energy conversion', '1. Describe how energy is converted from one form to another.', 230),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Energy', 'B8.4.1.1', 'Demonstrate the skill to evaluate the conversion of energy from one form to another', 'B8.4.1.1.2', 'Discuss the importance of conversion of energy', '1. Explain the processes that a dammed river goes through to produce electricity.; 2. Describe how to harness natural forms of energy into other forms.', 240),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Energy', 'B8.4.1.2', 'Show an understanding of the sources of renewable energy and how to manage these sources in a sustainable manner', 'B8.4.1.2.1', 'Describe renewable and non-renewable forms of energy', '1. Explain renewable and non-renewable sources of energy.; 2. Identify the various sources of renewable and non-renewable forms of energy and classify them e.g. wind, coal, hydro, crude oil, natural gas, solar and biogas.; 3. Describe how to produce energy from a renewable source.', 250),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Energy', 'B8.4.1.2', 'Show an understanding of the sources of renewable energy and how to manage these sources in a sustainable manner', 'B8.4.1.2.2', 'Demonstrate how to manage sources of renewable energy sustainably', '1. Research about information on the stages involved in managing renewable energy sources.; 2. Create a table to describe challenges associated with the management of different sources of renewable energy.', 260),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Energy', 'B8.4.1.3', 'Demonstrate an understanding of the relationship between heat and temperature', 'B8.4.1.3.1', 'Discuss the differences and the relationship between heat and temperature in the environment', '1. Create a table to show the distinguishing features of temperature and heat.; 2. Discuss the relationship between temperature and heat.', 270),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Electricity and Electronics', 'B8.4.2.1', 'Demonstrate knowledge of electricity transmission', 'B8.4.2.1.1', 'Explain how electricity transmission occurs', '1. Identify different stages of electricity transmission.; 2. Draw a flow chart to show the stages of electricity transmission from the point of generation to the point of consumption.', 280),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Electricity and Electronics', 'B8.4.2.2', 'Demonstrate understanding of the functions of capacitors in relation to LEDs, Diodes and resistors in electronic circuits', 'B8.4.2.2.1', 'Demonstrate the charging and discharging action of a capacitor in a DC electronic circuit', '1. Research information about capacitors in electronic circuits and explain their functions when connected with direct current (DC).; 2. Describe the charging and discharging actions of a capacitor and explain the role of LEDs, diodes and resistors in an electronic circuit.', 290),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Conversion and Conservation of Energy', 'B8.4.3.1', 'Evaluate the impact of conversion of energy and energy conservation on the environment', 'B8.4.3.1.1', 'Explain the importance of conversion of energy and energy conservation in daily life', '1. Classify the importance of energy conversion and energy conservation in daily life.; 2. Search from multimedia sources, books, internet for information on the impact of energy.; 3. Conversion and conservation in their environment, and make a poster presentation on their findings.', 300),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Force and Motion', 'B8.4.4.1', 'Demonstrate the production of magnet, domestic and industrial application of Magnetic force and its relationship with Newton’s Second law of motion and in everyday life', 'B8.4.4.1.1', 'Demonstrate simple ways of making magnets and show how magnetic force can be applied in domestic and industrial activities', 'Exemplars: 1. Produce magnets (using magnetic materials such as pieces of iron and bar magnet; and electricity). 2. Demonstrate some application of magnetic force in domestic and industrial activities (E. g. compass, alarms, loud speakers, etc.). 3. Explore other industrial and domestic applications of magnetic force and present findings.', 310),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Force and Motion', 'B8.4.4.1', 'Demonstrate the production of magnet, domestic and industrial application of Magnetic force and its relationship with Newton’s Second law of motion and in everyday life', 'B8.4.4.1.2', 'Explain the relationship between magnetic force and Newton’s Second Law of motion; and show the law’s application to life', '1. Explain Newton’s Second Law of motion with examples from daily life.; 2. Perform an experiment to show the relationship between force and motion using magnetic force, and the principle of Newton’s Second Law of Motion.', 320),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Force and Motion', 'B8.4.4.2', 'Demonstrate understanding of complex machines and how they work', 'B8.4.4.2.1', 'Identify complex machines and describe their functions in life', '1. Recap what simple machines are from', 330),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Agricultural Tools', 'B8.4.5.1', 'Demonstrate knowledge and skills in the use of basic and simple agricultural tools for basic on-farm activities', 'B8.4.5.1.1', 'Show and discuss the use of basic and simple agricultural tools for basic on-farm activities', '1. Collect and list different types of agricultural tools used for on-farm activities.; 2. Match each tool with the familiar type of agricultural activity it is used for and create an album of the tools.', 340),
('Basic 8', 'Science', 'science', 'Forces and Energy', 'Agricultural Tools', 'B8.4.5.1', 'Demonstrate knowledge and skills in the use of basic and simple agricultural tools for basic on-farm activities', 'B8.4.5.1.2', 'Engage in the use of basic and simple agricultural tools for basic farm activities', '1. Explain how the different agricultural tools are used on a farm or school garden to perform specific agricultural activities.; 2. Practice the use of different agricultural tools for specific activities on a farm or school garden.; 3. Select appropriate tools for specific agriculture tasks.', 350),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Waste Management', 'B8.5.1.1', 'Demonstrate knowledge of waste management systems and apply it in an environment', 'B8.5.1.1.1', 'Explain sustainable waste management practices', '1. Outline approaches to waste management in promoting sustainable management.; 2. Conduct a survey in a community’s waste management practices and present a report.', 360),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Waste Management', 'B8.5.1.1', 'Demonstrate knowledge of waste management systems and apply it in an environment', 'B8.5.1.1.2', 'Apply knowledge of waste management practices to manage waste in a community', '1. Carry out an activity to manage waste using knowledge acquired in indicator', 370),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Human Health', 'B8.5.2.1', 'Demonstrate knowledge of common communicable diseases, such as Hepatitis, of humans, causes, symptoms, effects and their prevention', 'B8.5.2.1.1', 'Explain the symptoms, effects and prevention of common communicable diseases', '1. Compile data on the number of males and females who suffer from common communicable diseases such as hepatitis, from a medical centre and determine the possible causes of these diseases.; 2. Identify causes, symptoms, effects and prevention of hepatitis, HIV, measles and others and make a presentation.; 3. Search for the causes, symptoms and prevention of hepatitis and develop a plan to minimise the disease.', 380),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Human Health', 'B8.5.2.1', 'Demonstrate knowledge of common communicable diseases, such as Hepatitis, of humans, causes, symptoms, effects and their prevention', 'B8.5.2.1.2', 'Analyse the risk factors of communicable diseases', '1. Search for information that is associated with communicable diseases.; 2. Create awareness about risk factors of communicable diseases such as hepatitis, HIV, measles and others in order to prevent the diseases in their schools and communities.', 390),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Human Health', 'B8.5.2.2', 'Demonstrate knowledge of the nature of selected bacterial diseases of humans, their causes, symptoms, effects and prevention', 'B8.5.2.2.1', 'Explain the nature of bacterial diseases with special emphasis on food poisoning/gonorrhoea/ meningitis their causes, symptoms, effects on humans and prevention', '1. Discuss the nature of bacterial diseases.; 2. Search for information and make presentations on food poisoning, gonorrhoea, and meningitis diseases their mode of transmission from person to person, community to community and from country to country.; 3. Describe the symptoms, effects and prevention of food poisoning,, gonorrhoea, and meningitis diseases.; 4. Describe the role of individuals, community members and government in managing food poisoning, gonorrhoea, and meningitis diseases.; 5. Design and produce a poster to educate their community members on the incidence and control of named bacterial diseases: food poisoning, gonorrhoea, and meningitis.', 400),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Science and Industry', 'B8.5.3.1', 'Demonstrate an understanding of connections among science, technology, innovation, society and the environment', 'B8.5.3.1.1', 'Examine the relationship among science, technology, innovation and society', '1. Explain the interrelationship of science and technology and innovation.; 2. Discuss technological advancements in the world and its impact on the Ghanaian environment.', 410),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Climate Change and Green Economy', 'B8.5.4.1', 'Demonstrate an understanding of the effects of climate change in the world and greening of other tropical countries including Ghana', 'B8.5.4.1.1', 'Explain the concept of climate change and its effect on the environment', '1. Describe the signs of climate change.; 2. Search for causes and effects of climate change and present a report.; 3. Explain how countries in the continents are adapting to climate change for example tree planting and legislation on bush burning.', 420),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Climate Change and Green Economy', 'B8.5.4.1', 'Demonstrate an understanding of the effects of climate change in the world and greening of other tropical countries including Ghana', 'B8.5.4.1.2', 'Describe climate change and green economy actions', '1. Describe climate change adaptation measures that can be applied in the community.; 2. Discuss mitigation strategies that your community can adapt to reduce the effects of climate change.', 430),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Understanding the Environment', 'B8.5.5.1', 'Demonstrate understanding of the differences among soils, plant roots, stems, leaves, flowers, and fruits of plants in the different environments', 'B8.5.5.1.1', 'Discuss physical properties of soils', '1. Collect and describe different samples of soils (sandy soil, loamy soil, clay soil, etc.) from the school garden and the community.; 2. Discuss how each soil type retains water and supports the root system of plants.; 3. Conduct an experiment to demonstrate how different soil types retain water to support the root system of crops.', 440),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Understanding the Environment', 'B8.5.5.1', 'Demonstrate understanding of the differences among soils, plant roots, stems, leaves, flowers, and fruits of plants in the different environments', 'B8.5.5.1.2', 'Analyse the physical properties of soils and soil water content and demonstrate their importance in crop production', '1. Examine and discuss the different physical properties of each soil type and how these properties help support crop production.; 2. Observe and describe the growth of different plants on different soil types.; 3. Demonstrate how plants absorb water and nutrients from the soil (osmosis).', 450),
('Basic 8', 'Science', 'science', 'Humans and the Environment', 'Understanding the Environment', 'B8.5.6.1', 'Recognise the different types of rocks as origin of different types of soils', 'B8.5.6.1.1', 'Observe and describe different types of rocks as origins of soils', '1. Identify different labelled samples of rocks presented in the classroom/ laboratory.; 2. Describe the visible characteristics of each rock.; 3. Collect samples of rocks from around the community and label them rock identification guide and compare them with the labelled laboratory samples in Exemplar; 1.; 4. Research and report the stages of weathering of rocks to form soil.', 460),
('Basic 8', 'Social Studies', 'social studies', 'Environment', 'Environmental Issues', 'B8.1.1.1', 'Demonstrate skills in dealing with environmental challenges', 'B8.1.1.1.1', 'Examine water pollution as an environmental challenge', '1. Explain pollution.; 2. Watch a documentary of polluted water bodies for discussion.', 10),
('Basic 8', 'Social Studies', 'social studies', 'Environment', 'Environmental Issues', 'B8.1.1.2', 'Analyse the sources and ways of conserving energy in Ghana', 'B8.1.1.2.1', 'Examine the means of conserving energy', '1. Explain energy conservation.; 2. Discuss responsible use of energy to minimise economic and environmental costs.', 20),
('Basic 8', 'Social Studies', 'social studies', 'Environment', 'Mapping Skills', 'B8.1.2.1', 'Demonstrate skills in sketching maps and interpreting landscapes from maps', 'B8.1.2.1.1', 'Sketch maps and interpret landscapes from maps', '1. Sketch a map of your school compound.; 2. Draw a diagram showing an eight-point compass (showing North, South, East and West; North East, North West, South East, South West).; 3. Using a map with grid squares, locate some important landmarks.', 30),
('Basic 8', 'Social Studies', 'social studies', 'Environment', 'Understanding Our Natural World', 'B8.1.3.1', 'Demonstrate understanding of the significance of weather and climate to the environment', 'B8.1.3.1.1', 'Assess the significance of weather and climate to the environment', '1. Explain the concepts: i. Climate ii. Weather; 2. Discuss the elements of climate, including temperature, humidity, atmospheric pressure and precipitation; 3. Discuss various ways of measuring the elements of weather and climate, including the use of hygrometer, rain gauge and barometer.', 40),
('Basic 8', 'Social Studies', 'social studies', 'Environment', 'Understanding Our Natural World', 'B8.1.3.2', 'Demonstrate understanding of natural disasters and their management', 'B8.1.3.2.1', 'Discuss natural disasters', '1. Watch some documentaries on natural disasters.; 2. Examine natural disasters and share the understanding of the term, including the idea that it involves great damage and also loss of lives. Examples of natural disasters are flooding, rainstorms, earthquake, volcanoes, wildfires and drought.', 50),
('Basic 8', 'Social Studies', 'social studies', 'Family Life', 'The Family', 'B8.2.2.1', 'Show understanding of the family and family life issues', 'B8.2.2.1.1', 'Examine the composition and functions of the nuclear and the extended families', '1. Explain the concept of family.; 2. Differentiate nuclear from extended family systems.; 3. Identify the roles of various members of the nuclear family.; 4. Explain the roles of the extended family.', 60),
('Basic 8', 'Social Studies', 'social studies', 'Family Life', 'The Family', 'B8.2.2.1', 'Show understanding of the family and family life issues', 'B8.2.2.1.2', 'Discuss the issues of inheritance in Ghana', '1. In pairs, discuss the concept of inheritance and share thoughts with the class.; 2. Identify and discuss the systems of inheritance in Ghana, including matrilineal, patrilineal and Intestate Succession.; 3. Invite a resource person in the community to talk about any of the systems of inheritance.; 4. Discuss the positive and negative effects of the inheritance systems in Ghana.; 5. Suggest ways of improving the indigenous inheritance system.', 70),
('Basic 8', 'Social Studies', 'social studies', 'Family Life', 'Population', 'B8.2.4.1', 'Analyse the population structure in Ghana and its related issues', 'B8.2.4.1.1', 'Compare the population structure of high-income and middle/low income countries', '1. Explain what population structure means.; 2. Draw/sketch the population structure of your school.; 3. Examine the population structure of Ghana as set out in a population pyramid.; 4. Examine the population structure of any developed country in the world, for example, China, Norway, Sweden, Singapore, Japan, and Canada.; 5. Discuss the population structures of low, middle and high-income countries.; 6. Suggest reasons for the population pyramids of low, middle and high- income countries with different shapes, including smaller families, higher standards of living, and high-quality healthcare.', 80),
('Basic 8', 'Social Studies', 'social studies', 'Sense of Purpose', 'The Individual and the Community', 'B8.3.1.1', 'Demonstrate knowledge of the role of the individual in the community', 'B8.3.1.1.2', 'Discuss the relevance of volunteerism to community development', '1. Explain the concept of volunteerism.; 2. Examine the ways by which one can volunteer in the community responsibly, including performing household chores, shopping or cleaning for an elderly person and helping clean the community.; 3. Identify some volunteering roles in the community and their contribution to community development, including reporting crime in the community to the police and avoiding taking the law into one’s own hands.', 90),
('Basic 8', 'Social Studies', 'social studies', 'Sense of Purpose', 'The Individual and the Community', 'B8.3.2.1', 'Demonstrate knowledge of the role of the individual in the community', 'B8.3.2.1.1', 'Examine the role of the individuals in the community', '1. Explain the concept of community.; 2. Watch a documentary about different communities and discuss observations.; 3. Explain what community development involves (the values vision, initiative and drive in the process of community development).; 6. Identify a specific need or problem of the community and show how learners can help solve it.', 100),
('Basic 8', 'Social Studies', 'social studies', 'Law and Order', 'Citizenship and Human Rights', 'B8.4.1.1', 'Investigate the rights and responsibilities of a citizen', 'B8.4.1.1.1', 'Examine the importance of human rights in the Ghanaian society', '1. Explain the concept “human rights”.; 2. Examine the United Nations declaration on human rights.; 3. Identify some examples of human rights enshrined in the 1992 constitution.; 4. Assess the importance of the protection of human rights.', 110),
('Basic 8', 'Social Studies', 'social studies', 'Law and Order', 'Conflict Prevention and Management', 'B8.4.2.1', 'Analyse ways of preventing and managing conflict', 'B8.4.2.1.1', 'Examine ways of preventing and managing conflict in the community', '1. Explain the following terms: i. Conflict ii. Conflict prevention iii. Conflict management; 2. Watch and discuss video or pictures on conflict and its effects on the larger society.; 3. Identify and discuss some causes of conflict in your community.', 120),
('Basic 8', 'Social Studies', 'social studies', 'Socio-economic Development', 'Financial and Investment Issues', 'B8.5.2.1', 'Demonstrate understanding of employer and employee relations in social security and pension', 'B8.5.2.1.1', 'Exhibit knowledge on employer and employee relation in social security and pension schemes', '1. Explain the following concepts: i. Employment ii. Employer iii. Employee; 2. Discuss the obligations of an employer in social security and pension schemes, including registering employees and paying their contributions regularly.; 3. In groups, discuss the obligations of an employee towards social security and pension schemes, including checking statement of contribution regularly and updating their records.', 130),
('Basic 8', 'Social Studies', 'social studies', 'Socio-economic Development', 'Tourism', 'B8.5.3.1', 'Evaluate tourism as an important economic sector for national development', 'B8.5.3.1.1', 'Assess the importance of tourism to socio-economic development of Ghana', '1. Use videos/pictures to identify some tourist sites.; 2. Visit tourist sites and suggest ways of improving them.; 3. Discuss how new tourist sites can be developed.', 140),
('Basic 8', 'Social Studies', 'social studies', 'Nationhood', 'The Republics', 'B8.6.2.1', 'Analyse the main developments in the Republics between 1960 and 1972', 'B8.6.2.1.1', 'Explain how the First Republic came into being', '1. Use the Internet, print media and oral sources to find out how the First Republic was established.; 2. Discuss the outcome of 27 April 1960 referendum.; 3. Discuss the outcome of 27 April 1960 presidential elections.; 4. Dramatise the inauguration of Kwame Nkrumah as president of the First Republic on 1 July 1960; 5. Produce a chart showing major political events from 1951 to1960.', 150),
('Basic 8', 'Social Studies', 'social studies', 'Nationhood', 'The Republics', 'B8.6.2.1', 'Analyse the main developments in the Republics between 1960 and 1972', 'B8.6.2.1.2', 'Explain political developments under the first republic', '1. Identify the main features of the 1960 Constitution of the First Republic.', 160),
('Basic 8', 'Social Studies', 'social studies', 'Nationhood', 'The Republics', 'B8.6.2.1', 'Analyse the main developments in the Republics between 1960 and 1972', 'B8.6.2.1.3', 'Explain how the Second Republic came into being', '1. Use the internet, print media and oral sources to find out how the Second Republic was established.; 2. Discuss the outcome of the 1969 general elections.; 3. Dramatise the handing over of power from the National Liberation Council (NLC) to Dr K. A Busia’s Progress Party.; 4. Compare the First Republican Constitution and the second Republican Constitution.', 170),
('Basic 8', 'Social Studies', 'social studies', 'Nationhood', 'The Republics', 'B8.6.2.1', 'Analyse the main developments in the Republics between 1960 and 1972', 'B8.6.2.1.4', 'Explain political developments under the Second Republic', '1. Describe the main features of the 1969 Constitution of the Second Republic including the creation of the office of the Prime Minister.; 2. Explain the changes that happened in the country as a result of the 1969 Constitution of the Second Republic.; 3. Discuss the membership of the cabinet under the1969 Constitution.', 180);
